// Zapier Code by Zapier (JavaScript) step
// Input: mailContent — either the full JSON response from Notion MCP fetch,
//        or just the `text` field from within it
// Output: from, to, cc, subject, timestamp, messageId, threadId

let text = inputData.mailContent || '';

// If the input is the full JSON object, parse it and extract the text field
try {
  const parsed = JSON.parse(text);
  text = parsed.text || '';
} catch (e) {
  // Not JSON — assume it's already the text content, use as-is
}

// Empty-result shape, reused for early returns
function emptyResult(error) {
  return {
    error: error || '',
    from: '',
    to: '',
    toArray: '[]',
    cc: '',
    ccArray: '[]',
    subject: '',
    timestamp: '',
    dateRaw: '',
    messageId: '',
    threadId: ''
  };
}

// Extract the <mail> block content
const mailMatch = text.match(/<mail>([\s\S]*?)<\/mail>/);

if (!mailMatch) {
  return emptyResult('No <mail> block found in content');
}

const mailBody = mailMatch[1];

// Messages are delimited by "<br><br>---<br><br>" (with a leading one before
// the first message too). Split on the dash separator regardless of how many
// <br> or whitespace surround it, then drop empty segments.
const messages = mailBody
  .split(/(?:<br>|\s)*-{3,}(?:<br>|\s)*/)
  .map(s => s.trim())
  .filter(Boolean);

const latest = messages[0] || mailBody;

// Helper: extract a header value, anchored to the start of a line.
// Headers sit at the start of the block or immediately after a <br>, so we
// require that boundary. This prevents matching "Cc"/"To"/etc. substrings
// buried inside quoted reply chains or signatures.
function extractField(body, fieldName) {
  const regex = new RegExp(
    '(?:^|<br>)\\s*' + fieldName + ':\\s*(.+?)\\s*(?:<br>|$)',
    'i'
  );
  const match = body.match(regex);
  return match ? match[1].trim() : '';
}

// Helper: pull clean email addresses out of a header string. Guards against
// display-name noise leaking through from a mis-parsed chain.
function extractEmails(str) {
  return (str.match(/[\w.+-]+@[\w.-]+\.\w+/g) || []).map(s => s.toLowerCase());
}

// Extract core metadata from the latest message only
const from = extractField(latest, 'From');
const toRaw = extractField(latest, 'To');
const ccRaw = extractField(latest, 'Cc');
const subject = extractField(latest, 'Subject');
const messageId = extractField(latest, 'MessageId');

// Normalise To / Cc to clean address arrays for the Notion multi-select fields
const toAddrs = extractEmails(toRaw);
const ccAddrs = extractEmails(ccRaw);

// threadId comes from <properties>, which lives OUTSIDE the <mail> block —
// parse it from the full text, not the latest-message slice.
let threadId = '';
let dateRaw = '';
const propsMatch = text.match(/<properties>\s*([\s\S]*?)\s*<\/properties>/);
if (propsMatch) {
  try {
    const props = JSON.parse(propsMatch[1]);
    threadId = props['Gmail Thread ID'] || '';
    dateRaw = props['date:Date Received:start'] || '';
  } catch (e) {}
}

// Fallback: Date/Sent/Timestamp headers in the latest message block
if (!dateRaw) {
  dateRaw = extractField(latest, 'Date')
    || extractField(latest, 'Sent')
    || extractField(latest, 'Timestamp');
}

let timestamp = '';
if (dateRaw) {
  const parsed = new Date(dateRaw);
  timestamp = isNaN(parsed.getTime()) ? dateRaw : parsed.toISOString();
}

return {
  from: (extractEmails(from)[0] || from),
  to: toAddrs.join(', '),
  toArray: JSON.stringify(toAddrs),
  cc: ccAddrs.join(', '),
  ccArray: JSON.stringify(ccAddrs),
  subject,
  timestamp,
  dateRaw,
  messageId,
  threadId
};
